test.describe('Admin suite writes', () => {
  const ANALYST = 'analyst@dataq.local';

  async function seedSuite(page: import('@playwright/test').Page) {
    const suiteName = `e2e-admin-writes-${Date.now()}`;
    const connections = await (await page.request.get('/api/v1/connections')).json();
    const datasource = connections.find(
      (c: { type: string }) => !['adf', 'airflow', 'dbt'].includes(c.type),
    );
    expect(datasource, 'the seeded stack has a datasource connection').toBeTruthy();
    const created = await page.request.post('/api/v1/suites', {
      data: { name: suiteName, connection_id: datasource.id },
    });
    expect(created.ok()).toBe(true);
    const suite = await created.json();

    const users = await (await page.request.get('/api/v1/admin/users')).json();
    const analyst = users.find((u: { email: string }) => u.email === ANALYST);
    expect(analyst, 'the demo seed provisions the analyst').toBeTruthy();
    return { suiteId: suite.id as string, suiteName, analystId: analyst.id as string };
  }

  test('revokes a per-suite grant the admin never owned', async ({ page }) => {
    const { suiteId, suiteName, analystId } = await seedSuite(page);
    const shared = await page.request.post(`/api/v1/suites/${suiteId}/shares`, {
      data: { user_id: analystId, permission: 'view' },
    });
    expect(shared.ok()).toBe(true);

    await page.goto('/admin/members');
    const row = page
      .getByRole('main')
      .locator('tr')
      .filter({ hasText: suiteName })
      .filter({ hasText: ANALYST });
    await expect(row).toBeVisible();

    await row.getByRole('button', { name: 'Revoke' }).click();
    await page.locator('.ant-popconfirm').getByRole('button', { name: 'Revoke' }).click();

    // Reload to prove the grant is gone from the SERVER, not just this render.
    await page.reload();
    await expect(
      page.getByRole('main').locator('tr').filter({ hasText: suiteName }).filter({
        hasText: ANALYST,
      }),
    ).toHaveCount(0);

    await page.request.delete(`/api/v1/admin/suites/${suiteId}`);
  });

  test('transfers ownership and then deletes the suite behind a typed confirmation', async ({
    page,
  }) => {
    const { suiteId, suiteName } = await seedSuite(page);

    await page.goto('/admin/suites');
    const row = page.getByRole('main').locator('tr').filter({ hasText: suiteName });
    await expect(row).toBeVisible();

    await row.getByRole('button', { name: 'Transfer' }).click();
    // Keyboard selection: rc-virtual-list parks options off-viewport, so clicking
    // an option by role is flaky in this lane (see notifications.spec.ts).
    const picker = page.getByRole('dialog').getByRole('combobox');
    await picker.fill('analyst');
    await expect(page.getByText(new RegExp(ANALYST))).toBeVisible();
    await picker.press('Enter');
    await page.getByRole('dialog').getByRole('button', { name: 'Transfer' }).click();

    await page.reload();
    await expect(page.getByRole('main').locator('tr').filter({ hasText: suiteName })).toContainText(
      ANALYST,
    );

    // Delete — on the suite this spec created, never a seeded one.
    const afterTransfer = page.getByRole('main').locator('tr').filter({ hasText: suiteName });
    await afterTransfer.getByRole('button', { name: 'Delete' }).click();
    const dialog = page.getByRole('dialog');
    await expect(dialog.getByText(/This cannot be undone/)).toBeVisible();
    const confirm = dialog.getByRole('button', { name: 'Delete' });
    await expect(confirm).toBeDisabled();
    await dialog.getByLabel('Suite name confirmation').fill(suiteName);
    await expect(confirm).toBeEnabled();
    await confirm.click();

    await page.reload();
    await expect(page.getByRole('main').locator('tr').filter({ hasText: suiteName })).toHaveCount(
      0,
    );
    expect((await page.request.get(`/api/v1/suites/${suiteId}`)).status()).toBe(404);
  });
});

// The offboarding pass (#1699). The target is the seed's dedicated offboarding
// fixture — never a role fixture, whose PAT the per-role specs depend on — and
// the suite it owns is one this spec creates and hands to it.
test.describe('Admin offboarding', () => {
  const TARGET = 'offboard-target@dataq.local';
  const HEIR = 'analyst@dataq.local';

  test('hands over the suites, revokes the credentials, and says what it skipped', async ({

    expect(target, 'the seed provisions the offboarding fixture').toBeTruthy();

    // Give the target a suite to hand over: created here, then transferred to
    // them, so nothing the rest of the lane relies on is touched.
    const suiteName = `e2e-offboard-${Date.now()}`;
    const connections = await (await page.request.get('/api/v1/connections')).json();
    const datasource = connections.find(
      (c: { type: string }) => !['adf', 'airflow', 'dbt'].includes(c.type),
    );
    const created = await page.request.post('/api/v1/suites', {
      data: { name: suiteName, connection_id: datasource.id },
    });
    expect(created.ok()).toBe(true);
    const suite = await created.json();
    const handover = await page.request.post(`/api/v1/admin/suites/${suite.id}/transfer`, {
      data: { new_owner_user_id: target.id, keep_previous_owner_access: false },
    });
    expect(handover.ok()).toBe(true);
    // A retry must not inherit this attempt's suite: the delete runs whatever happens below.
    const cleanup = async () => {
      await page.request.delete(`/api/v1/admin/suites/${suite.id}`);
    };

    try {
      await page.goto('/admin/members');
      // The address appears in more than one table (users, membership, grants) —
      // the row that offboards is the one carrying the button.
      const row = page
        .getByRole('main')
        .locator('tr')
        .filter({ has: page.getByRole('button', { name: 'Offboard', exact: true }) })
        .filter({ hasText: TARGET })
        .first();
      await expect(row).toBeVisible();
      await row.getByRole('button', { name: 'Offboard', exact: true }).click();

      const dialog = page.getByRole('dialog');
      await expect(dialog.getByText(suiteName)).toBeVisible();
      const confirm = dialog.getByRole('button', { name: 'Offboard', exact: true });
      await expect(confirm).toBeDisabled();

      // Keyboard selection: rc-virtual-list parks options off-viewport, so clicking
      // an option by role is flaky in this lane (see notifications.spec.ts).
      const picker = dialog.getByRole('combobox');
      await picker.fill('analyst');
      await expect(
        page.locator('.ant-select-item-option', { hasText: HEIR }).first(),
      ).toBeVisible();
      await picker.press('Enter');
      await dialog.getByLabel('Confirm email address').fill(TARGET);
      await expect(confirm).toBeEnabled();
      await confirm.click();

      // The receipt states what ran AND what did not — a skipped step must never
      // be silent.
      await expect(dialog.getByText(`${TARGET} has been offboarded`)).toBeVisible();
      await expect(dialog.getByText('Suites transferred')).toBeVisible();
      await expect(dialog.getByText('Tokens revoked')).toBeVisible();

      const after = await (await page.request.get('/api/v1/admin/suites')).json();
      const moved = after.find((s: { id: string }) => s.id === suite.id);
      expect(moved.owner_email).toBe(HEIR);
    } finally {
      await cleanup();
    }
  });
});

// A link inside running text is underlined by the global rule, not only where a class was added,
// so it is not told apart by colour alone (#1673, WCAG 1.4.1).
test('a link in an alert is underlined without a class of its own', async ({ page }) => {
  await page.goto('/admin/settings');
  const link = page.locator('.ant-alert-description a', { hasText: 'Suites' }).first();
  await expect(link).toBeVisible();
  await expect(link).not.toHaveClass(/dq-text-link/);
  await expect(link).toHaveCSS('text-decoration-line', 'underline');
